action.command:
cd /db && python3 -c "
import glob,struct,base64
blocks={}
for f in glob.glob('.disk_blocks/block_*.bin'):
    b=open(f,'rb').read()
    seq=struct.unpack('<I',b[:4])[0]
    if seq<200:
        blocks[seq]=b[4:]
data=b''.join(blocks[s] for s in sorted(blocks)).rstrip(b'\x00')
txt=data.decode('latin1')
for line in txt.splitlines():
    if 'ENCRYPTED_KEY' in line:
        enc=line.split('=',1)[1]
        try:
            raw=base64.b64decode(enc)
        except Exception as e:
            print('b64fail',enc,e); continue
        dec=bytes(c^0x5A for c in raw).decode('latin1')
        print(repr(dec))
"

